/**
 * Gallop frames for the brand horse.
 *
 * Derived from Eadweard Muybridge, "The Horse in Motion" (1878) -- public
 * domain. The 11 gallop plates were thresholded to silhouettes, the rider and
 * track lines removed, aligned on centre of mass and packed as 1-bit bitmaps
 * (132x49 cells, row-major, MSB first, base64).
 *
 * GENERATED by scripts/build_horse_frames.py -- do not edit by hand.
 */
export const HORSE_COLS = 132;
export const HORSE_ROWS = 49;
export const HORSE_FRAMES: readonly string[] = [
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
];

/** 1-bit pixel horse (32x19) as one SVG path, for the logo mark. */
export const HORSE_MARK_W = 32;
export const HORSE_MARK_H = 19;
export const HORSE_MARK_PATH =
  "M26 1h3v1h-3zM25 2h5v1h-5zM24 3h7v1h-7zM23 4h9v1h-9zM7 5h20v1h-20zM30 5h2v1h-2zM3 6h23v1h-23zM1 7h5v1h-5zM9 7h16v1h-16zM1 8h2v1h-2zM8 8h17v1h-17zM8 9h19v1h-19zM7 10h5v1h-5zM15 10h14v1h-14zM5 11h6v1h-6zM24 11h2v1h-2zM4 12h2v1h-2zM7 12h3v1h-3zM25 12h1v1h-1zM3 13h2v1h-2zM7 13h2v1h-2zM25 13h2v1h-2zM1 14h3v1h-3zM7 14h1v1h-1zM26 14h1v1h-1zM7 15h1v1h-1zM27 15h1v1h-1zM7 16h2v1h-2zM28 16h2v1h-2zM5 17h4v1h-4zM28 17h2v1h-2z";

/** Decode one frame into a Uint8Array of 0/1 cells. */
export function decodeFrame(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(HORSE_COLS * HORSE_ROWS);
  for (let i = 0; i < out.length; i++) {
    out[i] = (bin.charCodeAt(i >> 3) >> (7 - (i & 7))) & 1;
  }
  return out;
}
